using NUnit.Framework;using Rootborn.Game.World;using UnityEditor.SceneManagement;using UnityEngine;namespace Rootborn.Tests.EditMode.UI{public sealed class TownReturnUtilityEntryTests{[Test]public void ReturnCleanupKeepsGameplayMenuEntriesButClosesStaleModalContent(){var scene=EditorSceneManager.NewPreviewScene();scene.name="Town";try{var root=new GameObject("ReturnMenuFixture");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(root,scene);string[] names={"WorldStateLogButton","CareerCandidateOpenButton","CareerInterestOpenButton","WorldStateLogRoot","ObjectiveJournalRoot"};foreach(var name in names){var g=new GameObject(name);g.transform.SetParent(root.transform,false);}TownReturnViewCleanup.Apply(scene);foreach(string name in new[]{"WorldStateLogButton","CareerCandidateOpenButton","CareerInterestOpenButton"})Assert.That(root.transform.Find(name).gameObject.activeSelf,Is.True,name+" is a gameplay entry, not stale debug UI");Assert.That(root.transform.Find("WorldStateLogRoot").gameObject.activeSelf,Is.False,"Return flow must close stale panel content");/* The Tab journal owns its own open state; hiding its root on arrival made Tab do nothing. */Assert.That(root.transform.Find("ObjectiveJournalRoot").gameObject.activeSelf,Is.True,"Return flow must not disable the Tab journal");}finally{EditorSceneManager.ClosePreviewScene(scene);}}[Test]public void LaterCleanupFramesDoNotCloseAPanelThePlayerReopened(){var scene=EditorSceneManager.NewPreviewScene();scene.name="Town";try{var modal=new GameObject("WorldStateLogRoot");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(modal,scene);TownReturnViewCleanup.Apply(scene);Assert.That(modal.activeSelf,Is.False);modal.SetActive(true);var runner=System.Array.Find(scene.GetRootGameObjects(),x=>x.name=="[TownReturnViewCleanup]").GetComponent<MonoBehaviour>();var iterator=(System.Collections.IEnumerator)runner.GetType().GetMethod("Start",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(runner,null);Assert.That(iterator.MoveNext(),Is.True);Assert.That(modal.activeSelf,Is.True,"Cleanup must close each stale object once, not fight a fresh menu open for120 frames");}finally{EditorSceneManager.ClosePreviewScene(scene);}}}}